/// <summary>
/// CB714_POConfirmationReports
/// The <c>METPurchPurchaseOrderControllerExt</c> class starts the MET Purchase order report.
/// </summary>
class METPurchPurchaseOrderControllerExt extends PurchPurchaseOrderController
{
}

Method.Source:
/// <summary>
/// Instantiate METPurchPurchaseOrderControllerExt controller
/// </summary>
/// <returns>METPurchPurchaseOrderControllerExt instance</returns>
public static METPurchPurchaseOrderControllerExt construct()
{
    return new METPurchPurchaseOrderControllerExt();
}

/// <summary>
/// Constructs the controller class and sets the report design at run time
/// </summary>
/// <param name = "_args"> vendPurchOrderJour buffer</param>
public static void main(Args _args)
{
    METPurchPurchaseOrderControllerExt controller = METPurchPurchaseOrderControllerExt::construct();
    VendPurchOrderJour vendPurchOrderJour = VendPurchOrderJour::findRecId(_args.record().RecId);

    if (vendPurchOrderJour)
    {
        PurchTable purchTable = PurchTable::find(vendPurchOrderJour.PurchId);

        if (purchTable)
        {
            if (purchTable.vendTable_OrderAccount().VendGroup == METConstants::ImportPOVendorGroup && purchTable.PurchPoolId == METConstants::ImportPOPoolId)
            {
                controller.initArgs(_args, ssrsReportStr(METPurchPurchaseOrder, ReportImport));
            }
            else
            {
                controller.initArgs(_args, ssrsReportStr(METPurchPurchaseOrder, ReportTrade));
            }

            if (purchTable.getCountOflines() == purchTable.getCountOfLinesWithNegativeQty())
            {
                controller.initArgs(_args, ssrsReportStr(METPurchPurchaseOrder, ReportReturn));
            }
        }
    }

    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Set the report format name for the print setting detail.
/// </summary>
protected void outputReport()
{
    formletterReport.parmReportRun().settingDetail().parmReportFormatName(this.parmReportName());

    super();
}
